@@ -0,0 +1,37 @@
+// Sites (kitchens). Every location belongs to one site, and everything kept
+// in a location (batches, stock-takes, temperature readings) belongs to that
+// location's site. Items, suppliers, recipes and dishes are shared.
+import { AppError } from "../errors.js";
+
+/** The site used when a caller names none. */
+export const DEFAULT_SITE = "main";
+
+/** Every site, in file order. */
+export function listSites(store) {
+  return [...store.data.sites];
+}
+
+/** One site, or AppError unknown_site. */
+export function getSite(store, id) {
+  const site = store.data.sites.find((s) => s.id === id);
+  if (!site) throw new AppError("unknown_site", { id });
+  return site;
+}
+
+/** The site a location id belongs to (the default site when the location is not listed). */
+export function siteOf(store, locationId) {
+  return store.data.locations.find((l) => l.id === locationId)?.site ?? DEFAULT_SITE;
+}
+
+/** One location of a site, or AppError unknown_location. */
+export function siteLocation(store, site, id) {
+  const location = store.data.locations.find((l) => l.id === id && l.site === site);
+  if (!location) throw new AppError("unknown_location", { id });
+  return location;
+}
+
+/** A test for records with a `location` (batches, stock-takes, readings): is it in `site`? */
+export function inSite(store, site) {
+  const sites = new Map(store.data.locations.map((l) => [l.id, l.site]));
+  return (record) => (sites.get(record.location) ?? DEFAULT_SITE) === site;
+}
